        } catch {
            okZero = false;
        }

        // General rule: after any completed ownership transfer, the owner is never
        // the zero address (and if transfer of zero reverted, owner stays non-zero).
        assertTrue((okZero && c.owner() != address(0)) || (!okZero && c.owner() != address(0)), "owner is never zero after transferOwnership");
    }
}

